-- Read-only access for one schema (current and future tables)
GRANT USE CATALOG ON CATALOG sales TO `analysts`;
GRANT USE SCHEMA, SELECT ON SCHEMA sales.reporting TO `analysts`;

-- Production objects are owned by a group, not a person
ALTER TABLE sales.reporting.orders OWNER TO `sales_data_owners`;

-- Delegate grant management without data access
GRANT MANAGE ON SCHEMA sales.reporting TO `sales_stewards`;
GRANT USE CATALOG ON CATALOG sales TO `sales_stewards`;

-- Make the catalog discoverable to everyone
GRANT BROWSE ON CATALOG sales TO `account users`;

-- Row filter: admins see all rows, others see US only
CREATE FUNCTION gov.fn.us_filter(region STRING)
RETURN IF(is_account_group_member('admin'), true, region = 'US');

ALTER TABLE sales.core.orders SET ROW FILTER gov.fn.us_filter ON (region);

-- Column mask: show the last 4 digits unless in hr_admins
CREATE FUNCTION gov.fn.ssn_mask(ssn STRING)
RETURN CASE WHEN is_account_group_member('hr_admins') THEN ssn
            ELSE concat('***-**-', right(ssn, 4)) END;

ALTER TABLE hr.core.employees ALTER COLUMN ssn SET MASK gov.fn.ssn_mask;

-- Remove the filter before dropping its function
ALTER TABLE sales.core.orders DROP ROW FILTER;
DROP FUNCTION gov.fn.us_filter;

-- Step 2: delete many users at once in bronze
MERGE INTO crm.bronze.users AS t
USING (SELECT user_id FROM crm.ops.gdpr_requests) AS r
ON t.user_id = r.user_id
WHEN MATCHED THEN DELETE;

-- Step 3: streaming tables accept DML
DELETE FROM crm.silver.users_st WHERE user_id IN (SELECT user_id FROM crm.ops.gdpr_requests);

-- Step 4: rewrite files that still hold soft-deleted rows
REORG TABLE crm.bronze.users APPLY (PURGE);

-- Step 5: remove files older than the retention window (default 7 days)
VACUUM crm.bronze.users;

