ALTER TABLE sales.reporting.orders SET TAGS ('domain' = 'sales', 'tier' = 'gold');
ALTER TABLE sales.reporting.orders ALTER COLUMN email SET TAGS ('pii' = 'email');

COMMENT ON TABLE sales.reporting.orders IS 'One row per order line, refreshed hourly';
COMMENT ON COLUMN sales.reporting.orders.email IS 'Customer email, masked by policy';

SELECT table_name, column_name, tag_name, tag_value
FROM sales.information_schema.column_tags
WHERE tag_name = 'pii';
